diagrams.content:
flowchart TD
  A["Message arrives at a<br/>plausible moment"] --> B{"Do you notice<br/>anything wrong?"}
  B -->|"Often not — timing<br/>and branding are right"| C["You open the link"]
  C --> D{"Password manager<br/>asked to autofill?"}
  D -->|"Domain mismatch"| E["Silently refuses:<br/>a reliable warning"]
  D -->|"You type it manually"| F["Credentials captured"]
  F --> G{"Second factor type?"}
  G -->|"Code you retype"| H["Relayed in real time"]
  G -->|"Passkey, bound to<br/>the real domain"| I["Produces nothing:<br/>attack fails"]
